689	  protected RequestInterceptor createRequestInterceptorChain() {
690	    Configuration conf = getConfig();
691	
692	    List<String> interceptorClassNames = getInterceptorClassNames(conf);
693	
694	    RequestInterceptor pipeline = null;
695	    RequestInterceptor current = null;
696	    for (String interceptorClassName : interceptorClassNames) {
697	      try {
698	        Class<?> interceptorClass =
699	            conf.getClassByName(interceptorClassName);
700	        if (RequestInterceptor.class.isAssignableFrom(interceptorClass)) {
701	          RequestInterceptor interceptorInstance =
702	              (RequestInterceptor) ReflectionUtils.newInstance(
703	                  interceptorClass, conf);
704	          if (pipeline == null) {
705	            pipeline = interceptorInstance;
706	            current = interceptorInstance;
707	            continue;
708	          } else {
709	            current.setNextInterceptor(interceptorInstance);
710	            current = interceptorInstance;
711	          }
712	        } else {
713	          throw new YarnRuntimeException("Class: " + interceptorClassName
714	              + " not instance of "
715	              + RequestInterceptor.class.getCanonicalName());
716	        }
717	      } catch (ClassNotFoundException e) {
718	        throw new YarnRuntimeException(
719	            "Could not instantiate ApplicationMasterRequestInterceptor: "
720	                + interceptorClassName, e);
721	      }
722	    }
723	
724	    if (pipeline == null) {
725	      throw new YarnRuntimeException(
726	          "RequestInterceptor pipeline is not configured in the system");
727	    }
